self.KB_CONTENT["card:89833"]={"id":"card:89833","ty":"card","sourceId":"89833","title":"請問在新增會計總帳管理系統中->日常異動處理->『會計傳票建立作業』之【總帳帳別】預設帳別資料來源是?","ver":"GP4X","topic":"總帳帳別","keywords":["總帳帳別","傳票","異動"],"y":"other","answer":"『會計傳票建立作業』之【總帳帳別】預設帳別資料來源為『會計系統參數設定作業』的【主要帳別】。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
