self.KB_CONTENT["card:756470"]={"id":"card:756470","ty":"card","sourceId":"756470","title":"『商品預計出貨明細表』的作業重點有哪些？","ver":"iGP","topic":"明細表","keywords":["明細表","訂單","單位","出貨"],"y":"explain","answer":"1.訂單數量及已交數量：當為雙單位時，總計到整數位。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
