self.KB_CONTENT["card:753055"]={"id":"card:753055","ty":"card","sourceId":"753055","title":"『越南明細分類帳』中的『選擇傳票日期 (ACT.ML002)』為何？","ver":"iGP","topic":"明細","keywords":["明細","傳票","分類"],"y":"other","answer":"* 可點選(icon)或[F2]日期快手查詢。若空白表全部。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
