self.KB_CONTENT["field:889215"]={"id":"field:889215","ty":"field","sourceId":"889215","title":"會計科目","ver":"AiGP 1.1.0以上","topic":"","keywords":[],"job":"付款單建立作業","code":"","answer":"『付款單建立作業-ACPI03』類別如果為\"沖帳\"【會計科目】會先取『供應廠商資料建立作業-PURI01』中的【應付帳款科目】，若為空白則抓取『單據性質設定作業-ACPI01』該應付憑單單別對應的【會計科目】，","file":"fields.jsonl"};
