self.KB_CONTENT["field:772047"]={"id":"field:772047","ty":"field","sourceId":"772047","title":"工程帳務方式","ver":"GP4.X","topic":"","keywords":[],"job":"專案人工傳票產生/還原作業","code":"","answer":"請在『交易對象分類建立作業-EPMI41』設定【分類方式】為'G':專案帳務類型的不同代號之立相關科目後，再至『專案代號建立作業-EPMI14』設定【專案帳務類型】對應的代號，即可不同的專案設定不同的科目，後續執行『專案人工傳票產生/還原作業-EPMB29』時優先取專案代號設定的專案帳務類型代號之科目。","file":"fields.jsonl"};
